static inline __attribute__((always_inline)) void row36_in(const double* s, double* pr, double* pi){
    { V a=VLU(s+0), b=VLU(s+8);
      VS(pr+0, PERM2(a, IDXR_, b)); VS(pi+0, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+16), b=VLU(s+24);
      VS(pr+8, PERM2(a, IDXR_, b)); VS(pi+8, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+32), b=VLU(s+40);
      VS(pr+16, PERM2(a, IDXR_, b)); VS(pi+16, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+48), b=VLU(s+56);
      VS(pr+24, PERM2(a, IDXR_, b)); VS(pi+24, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+64); V b=_mm512_maskz_loadu_pd(0x0, s+72);
      VS(pr+32, PERM2Z(0xf, a, IDXR_, b)); VS(pi+32, PERM2Z(0xf, a, IDXI_, b)); }
}

static void sw36_SyX(int y0, const double* cvol, double* o1, double* om, int pre){
    double* br = A36R + (long)y0*RS36;
    double* bi = A36I + (long)y0*RS36;
    for (int ch = 0; ch < 5; ch++) {
        long so = (long)y0*36 + ch*8;
        int tail = (ch == 4) && 1;
        const double* ccr = C36R + (long)y0*RS36 + ch*8;
        const double* cci = C36I + (long)y0*RS36 + ch*8;
        wv36A_ps(br + ch*8, bi + ch*8);
        if (o1 && om) wv36Bm2_ps(br + ch*8, bi + ch*8, ccr, cci, 1296, o1 + 2*so, om + 2*so, tail);
        else if (o1)  wv36Bm1_ps(br + ch*8, bi + ch*8, ccr, cci, 1296, o1 + 2*so, tail);
        else if (om)  wv36Bm1_ps(br + ch*8, bi + ch*8, ccr, cci, 1296, om + 2*so, tail);
        else          wv36Bm0_ps(br + ch*8, bi + ch*8, ccr, cci, 1296, tail);
    }
    if (pre) {
        for (int b = 0; b < 5; b++) wvz36_ps(br + (long)b*8*PS36, bi + (long)b*8*PS36, b<4?8:4);
        for (int ch = 0; ch < 5; ch++) { wv36A_ps(br + ch*8, bi + ch*8); wv36B_ps(br + ch*8, bi + ch*8); }
    }
}
static void sw36_PxY(int x0, const double* cvol, double* o1, double* om, int pre){
    double* br = A36R + (long)x0*PS36;
    double* bi = A36I + (long)x0*PS36;
    for (int ch = 0; ch < 5; ch++) {
        long so = (long)x0*1296 + ch*8;
        int tail = (ch == 4) && 1;
        const double* ccr = C36R + (long)x0*PS36 + ch*8;
        const double* cci = C36I + (long)x0*PS36 + ch*8;
        wv36A_rs(br + ch*8, bi + ch*8);
        if (o1 && om) wv36Bm2_rs(br + ch*8, bi + ch*8, ccr, cci, 36, o1 + 2*so, om + 2*so, tail);
        else if (o1)  wv36Bm1_rs(br + ch*8, bi + ch*8, ccr, cci, 36, o1 + 2*so, tail);
        else if (om)  wv36Bm1_rs(br + ch*8, bi + ch*8, ccr, cci, 36, om + 2*so, tail);
        else          wv36Bm0_rs(br + ch*8, bi + ch*8, ccr, cci, 36, tail);
    }
    if (pre) {
        for (int b = 0; b < 5; b++) wvz36_rs(br + (long)b*8*RS36, bi + (long)b*8*RS36, b<4?8:4);
        for (int ch = 0; ch < 5; ch++) { wv36A_rs(br + ch*8, bi + ch*8); wv36B_rs(br + ch*8, bi + ch*8); }
    }
}
void run_36wv(const double* x0, const double* c, double* out1, double* outm, long B, long m){
    if (m < 1) m = 1;
    for (long b = 0; b < B; b++) {
        const double* xv = x0 + b*2*46656;
        const double* cv = c + b*2*46656;
        double* o1 = out1 + b*2*46656;
        double* om = outm + b*2*46656;
        for (int x = 0; x < 36; x++)
            for (int y = 0; y < 36; y++) {
                row36_in(xv + ((long)x*36+y)*72, A36R + (long)x*PS36 + y*RS36,
                         A36I + (long)x*PS36 + y*RS36);
                row36_in(cv + ((long)x*36+y)*72, C36R + (long)x*PS36 + y*RS36,
                         C36I + (long)x*PS36 + y*RS36);
            }
        for (int x = 0; x < 36; x++) {
            double* br = A36R + (long)x*PS36; double* bi = A36I + (long)x*PS36;
            for (int bnd = 0; bnd < 5; bnd++) wvz36_rs(br + (long)bnd*8*RS36, bi + (long)bnd*8*RS36, bnd<4?8:4);
            for (int ch = 0; ch < 5; ch++) { wv36A_rs(br + ch*8, bi + ch*8); wv36B_rs(br + ch*8, bi + ch*8); }
        }
        for (long t = 1; t <= m; t++) {
            double* o1t = (t==1) ? o1 : 0;
            double* omt = (t==m) ? om : 0;
            int pre = (t < m);
            if (t & 1) { for (int y0 = 0; y0 < 36; y0++) sw36_SyX(y0, cv, o1t, omt, pre); }
            else       { for (int xp = 0; xp < 36; xp++) sw36_PxY(xp, cv, o1t, omt, pre); }
        }
    }
}

