    V w0_0r, w0_0i, w0_1r, w0_1i, w0_2r, w0_2i, w1_0r, w1_0i, w1_1r, w1_1i, w1_2r, w1_2i, w2_0r, w2_0i, w2_1r, w2_1i, w2_2r, w2_2i;
