      w0_0r=VADD(a0r,ur); w0_0i=VADD(a0i,ui);
      w0_1r=VFMA(vi,VSET1(0x1.bb67ae8584caap-1),sr);
      w0_1i=VFNMA(vr,VSET1(0x1.bb67ae8584caap-1),si);
      w0_2r=VFNMA(vi,VSET1(0x1.bb67ae8584caap-1),sr);
      w0_2i=VFMA(vr,VSET1(0x1.bb67ae8584caap-1),si);
