        r1 = (nrows > 1) ? VL(pi + 1*2160 + t*8) : _mm512_setzero_pd();
        r2 = (nrows > 2) ? VL(pi + 2*2160 + t*8) : _mm512_setzero_pd();
        r3 = (nrows > 3) ? VL(pi + 3*2160 + t*8) : _mm512_setzero_pd();
        r4 = (nrows > 4) ? VL(pi + 4*2160 + t*8) : _mm512_setzero_pd();
