        r1 = VL(ZR45 + (t*8+1)*8);
        r2 = VL(ZR45 + (t*8+2)*8);
        r3 = VL(ZR45 + (t*8+3)*8);
        r4 = VL(ZR45 + (t*8+4)*8);
        r5 = VL(ZR45 + (t*8+5)*8);
        r6 = VL(ZR45 + (t*8+6)*8);
        r7 = VL(ZR45 + (t*8+7)*8);
        TR8(r0,r1,r2,r3,r4,r5,r6,r7);
        if (nrows > 0) VS(pr + 0*2160 + t*8, r0);
        if (nrows > 1) VS(pr + 1*2160 + t*8, r1);
        if (nrows > 2) VS(pr + 2*2160 + t*8, r2);
        if (nrows > 3) VS(pr + 3*2160 + t*8, r3);
        if (nrows > 4) VS(pr + 4*2160 + t*8, r4);
        if (nrows > 5) VS(pr + 5*2160 + t*8, r5);
        if (nrows > 6) VS(pr + 6*2160 + t*8, r6);
        if (nrows > 7) VS(pr + 7*2160 + t*8, r7);
        r0 = VL(ZI45 + (t*8+0)*8);
