        TR8(r0,r1,r2,r3,r4,r5,r6,r7);
        if (nrows > 0) VS(pi + 0*2160 + t*8, r0);
        if (nrows > 1) VS(pi + 1*2160 + t*8, r1);
        if (nrows > 2) VS(pi + 2*2160 + t*8, r2);
