        TR8(r0,r1,r2,r3,r4,r5,r6,r7);
        if (nrows > 0) VS(pr + 0*4104 + t*8, r0);
        if (nrows > 1) VS(pr + 1*4104 + t*8, r1);
        if (nrows > 2) VS(pr + 2*4104 + t*8, r2);
        if (nrows > 3) VS(pr + 3*4104 + t*8, r3);
        if (nrows > 4) VS(pr + 4*4104 + t*8, r4);
