static inline __attribute__((always_inline)) void row64_in(const double* s, double* pr, double* pi){
    { V a=VLU(s+0), b=VLU(s+8);
      VS(pr+0, PERM2(a, IDXR_, b)); VS(pi+0, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+16), b=VLU(s+24);
      VS(pr+8, PERM2(a, IDXR_, b)); VS(pi+8, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+32), b=VLU(s+40);
      VS(pr+16, PERM2(a, IDXR_, b)); VS(pi+16, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+48), b=VLU(s+56);
      VS(pr+24, PERM2(a, IDXR_, b)); VS(pi+24, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+64), b=VLU(s+72);
      VS(pr+32, PERM2(a, IDXR_, b)); VS(pi+32, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+80), b=VLU(s+88);
      VS(pr+40, PERM2(a, IDXR_, b)); VS(pi+40, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+96), b=VLU(s+104);
      VS(pr+48, PERM2(a, IDXR_, b)); VS(pi+48, PERM2(a, IDXI_, b)); }
    { V a=VLU(s+112), b=VLU(s+120);
      VS(pr+56, PERM2(a, IDXR_, b)); VS(pi+56, PERM2(a, IDXI_, b)); }
}

static void sw64_SyX(int y0, const double* cvol, double* o1, double* om, int pre){
    double* br = A64R + (long)y0*RS64;
    double* bi = A64I + (long)y0*RS64;
    for (int ch = 0; ch < 8; ch++) {
        long so = (long)y0*64 + ch*8;
        int tail = (ch == 7) && 0;
        const double* ccr = C64R + (long)y0*RS64 + ch*8;
        const double* cci = C64I + (long)y0*RS64 + ch*8;
        wv64A_ps(br + ch*8, bi + ch*8);
        if (o1 && om) wv64Bm2_ps(br + ch*8, bi + ch*8, ccr, cci, 4096, o1 + 2*so, om + 2*so, tail);
        else if (o1)  wv64Bm1_ps(br + ch*8, bi + ch*8, ccr, cci, 4096, o1 + 2*so, tail);
        else if (om)  wv64Bm1_ps(br + ch*8, bi + ch*8, ccr, cci, 4096, om + 2*so, tail);
        else          wv64Bm0_ps(br + ch*8, bi + ch*8, ccr, cci, 4096, tail);
    }
    if (pre) {
        for (int b = 0; b < 8; b++) wvz64_ps(br + (long)b*8*PS64, bi + (long)b*8*PS64, b<7?8:8);
        for (int ch = 0; ch < 8; ch++) { wv64A_ps(br + ch*8, bi + ch*8); wv64B_ps(br + ch*8, bi + ch*8); }
    }
}
static void sw64_PxY(int x0, const double* cvol, double* o1, double* om, int pre){
    double* br = A64R + (long)x0*PS64;
    double* bi = A64I + (long)x0*PS64;
    for (int ch = 0; ch < 8; ch++) {
        long so = (long)x0*4096 + ch*8;
        int tail = (ch == 7) && 0;
        const double* ccr = C64R + (long)x0*PS64 + ch*8;
        const double* cci = C64I + (long)x0*PS64 + ch*8;
        wv64A_rs(br + ch*8, bi + ch*8);
        if (o1 && om) wv64Bm2_rs(br + ch*8, bi + ch*8, ccr, cci, 64, o1 + 2*so, om + 2*so, tail);
        else if (o1)  wv64Bm1_rs(br + ch*8, bi + ch*8, ccr, cci, 64, o1 + 2*so, tail);
        else if (om)  wv64Bm1_rs(br + ch*8, bi + ch*8, ccr, cci, 64, om + 2*so, tail);
        else          wv64Bm0_rs(br + ch*8, bi + ch*8, ccr, cci, 64, tail);
    }
    if (pre) {
        for (int b = 0; b < 8; b++) wvz64_rs(br + (long)b*8*RS64, bi + (long)b*8*RS64, b<7?8:8);
        for (int ch = 0; ch < 8; ch++) { wv64A_rs(br + ch*8, bi + ch*8); wv64B_rs(br + ch*8, bi + ch*8); }
    }
}
void run_64wv(const double* x0, const double* c, double* out1, double* outm, long B, long m){
    if (m < 1) m = 1;
    for (long b = 0; b < B; b++) {
        const double* xv = x0 + b*2*262144;
        const double* cv = c + b*2*262144;
        double* o1 = out1 + b*2*262144;
        double* om = outm + b*2*262144;
        for (int x = 0; x < 64; x++)
            for (int y = 0; y < 64; y++) {
                row64_in(xv + ((long)x*64+y)*128, A64R + (long)x*PS64 + y*RS64,
                         A64I + (long)x*PS64 + y*RS64);
                row64_in(cv + ((long)x*64+y)*128, C64R + (long)x*PS64 + y*RS64,
                         C64I + (long)x*PS64 + y*RS64);
            }
        for (int x = 0; x < 64; x++) {
            double* br = A64R + (long)x*PS64; double* bi = A64I + (long)x*PS64;
            for (int bnd = 0; bnd < 8; bnd++) wvz64_rs(br + (long)bnd*8*RS64, bi + (long)bnd*8*RS64, bnd<7?8:8);
            for (int ch = 0; ch < 8; ch++) { wv64A_rs(br + ch*8, bi + ch*8); wv64B_rs(br + ch*8, bi + ch*8); }
        }
        for (long t = 1; t <= m; t++) {
            double* o1t = (t==1) ? o1 : 0;
            double* omt = (t==m) ? om : 0;
            int pre = (t < m);
            if (t & 1) { for (int y0 = 0; y0 < 64; y0++) sw64_SyX(y0, cv, o1t, omt, pre); }
            else       { for (int xp = 0; xp < 64; xp++) sw64_PxY(xp, cv, o1t, omt, pre); }
        }
    }
}

